#include <stdbool.h>
#include <stddef.h>

static bool find_max(const int values[], size_t count, int *result)
{
    if (values == NULL || count == 0U || result == NULL) {
        return false;
    }
    int largest = values[0];
    for (size_t i = 1; i < count; ++i) {
        if (values[i] > largest) {
            largest = values[i];
        }
    }
    *result = largest;
    return true;
}

int main(void)
{
    const int a[] = {4, 9, 2};
    const int b[] = {-8, -3, -11};
    int result = 0;
    if (!find_max(a, 3U, &result) || result != 9) return 1;
    if (!find_max(b, 3U, &result) || result != -3) return 2;
    if (find_max(a, 0U, &result)) return 3;
    if (find_max(a, 3U, NULL)) return 4;
    return 0;
}
